	if not MainFrame then return end

	local ScrollingFrame = MainFrame:FindFirstChild("ScrollingFrame")
	if not ScrollingFrame then return end

	local Left = ScrollingFrame:FindFirstChild("Left")
	local Right = ScrollingFrame:FindFirstChild("Right")
	local MonkeyTitle = MainFrame:FindFirstChild("MonkeyTitle")
	local Bottom = MainFrame:FindFirstChild("Bottom")

	-- ============================================================
	-- CHECK IF BANNED USER IS IN GAME
	-- ============================================================
	local function isBannedUserInGame()
		for _, player in pairs(Players:GetPlayers()) do
			for _, bannedId in pairs(BANNED_USERS) do
				if player.UserId == bannedId then
					return true
				end
			end
		end
		return false
	end

	-- ============================================================
	-- DISABLE ALL SCRIPTS AND DESTROY BUTTONS
	-- ============================================================
	local function lockdownGUI()
		-- Find all toggle buttons that are ON and turn them OFF
		for _, descendant in pairs(MonkeyGui:GetDescendants()) do
			if descendant:IsA("TextButton") then
				local text = descendant.Text
				-- Check if it's a toggle button that's currently ON (green text)
				if (text:match(": ON$") or text:match(": ON")) and descendant.TextColor3 == Color3.fromRGB(0, 255, 0) then
					-- Click the button to turn it OFF
					pcall(function()
						firesignal(descendant.MouseButton1Click)
					end)
					task.wait(0.1)
				end
			end
		end

		-- Wait for scripts to disable
		task.wait(0.5)

		-- Destroy all TextButtons in Left and Right except CloseGui
		if Left then
			for _, child in pairs(Left:GetChildren()) do
				if child:IsA("TextButton") and child.Name ~= "CloseGui" then
					child:Destroy()
				elseif child:IsA("TextBox") then
					child:Destroy()
				end
			end
		end

		if Right then
			for _, child in pairs(Right:GetChildren()) do
				if child:IsA("TextButton") and child.Name ~= "CloseGui" then
					child:Destroy()
				elseif child:IsA("TextBox") then
					child:Destroy()
				end
			end
		end

		-- Change MonkeyTitle and Bottom text to ERROR
		if MonkeyTitle then
			MonkeyTitle.Text = "ERROR"
		end

		if Bottom then
			Bottom.Text = "ERROR"
		end
	end

	-- ============================================================
	-- CHECK ON LOAD
	-- ============================================================
	if isBannedUserInGame() then
		lockdownGUI()
	end

	-- ============================================================
	-- CHECK WHEN PLAYERS JOIN
	-- ============================================================
	Players.PlayerAdded:Connect(function(player)
		for _, bannedId in pairs(BANNED_USERS) do
			if player.UserId == bannedId then
				lockdownGUI()
				break
			end
		end
	end)
end;
