local function C_11()
local script = G2L["11"];
	local Players = game:GetService("Players")
	local TeleportService = game:GetService("TeleportService")
	local LocalPlayer = Players.LocalPlayer
	local PLACE_ID = game.PlaceId

	local AntiFreeze = script.Parent
	local isOn = false
	local isResetting = false

	local FILE_NAME = "monkeygang_rejoin_state.txt"
	local TIMESTAMP_FILE = "monkeygang_rejoin_timestamp.txt"

	-- ============================================================
	-- FIND MONKEYTITLE AND SCREENGUI
	-- ============================================================
	local function getScreenGui()
		local p = script.Parent
		while p do
			if p:IsA("ScreenGui") then
				return p
			end
			p = p.Parent
		end
	end

	local function findDescendant(name)
		local ScreenGui = getScreenGui()
		if not ScreenGui then return nil end
		for _, v in pairs(ScreenGui:GetDescendants()) do
			if v.Name == name then
				return v
			end
		end
	end

	local MonkeyTitle = findDescendant("MonkeyTitle")
	local ScreenGui = getScreenGui()

	-- ============================================================
	-- FILE SAVE/LOAD FUNCTIONS
	-- ============================================================
	local function readFile()
		local success, result = pcall(function()
			return readfile(FILE_NAME)
		end)
		if success and result and result ~= "" then return result end
		return nil
	end

	local function writeFile(content)
		pcall(function()
			writefile(FILE_NAME, content)
		end)
	end

	local function saveButtonStates()
		if not ScreenGui then return end

		local lines = {}
		table.insert(lines, "autoRejoin=true")

		for _, descendant in pairs(ScreenGui:GetDescendants()) do
			if descendant:IsA("TextButton") then
				local text = descendant.Text
				if text:match(": ON$") or text:match(": OFF$") then
					local isEnabled = descendant.TextColor3 == Color3.fromRGB(0, 255, 0)
					table.insert(lines, descendant.Name .. "=" .. tostring(isEnabled))
				end
			end
		end

		writeFile(table.concat(lines, "\n"))

		pcall(function()
			writefile(TIMESTAMP_FILE, tostring(tick()))
		end)
	end

	local function loadAndApplyStates()
		local timestampData = nil
		pcall(function()
			timestampData = readfile(TIMESTAMP_FILE)
		end)

		if not timestampData then return end

		local rejoinTime = tonumber(timestampData)
		if not rejoinTime then return end

		local timeSinceRejoin = tick() - rejoinTime

		if timeSinceRejoin > 30 then
			pcall(function()
				delfile(TIMESTAMP_FILE)
			end)
			return
		end

		local data = readFile()
		if not data then return end

		local states = {}
		for line in data:gmatch("[^\n]+") do
			local key, value = line:match("(.-)=(.+)")
			if key and value then
				states[key] = value
			end
		end

		if states["autoRejoin"] ~= "true" then return end

		if not ScreenGui then return end

		for _, descendant in pairs(ScreenGui:GetDescendants()) do
			if descendant:IsA("TextButton") then
				local savedState = states[descendant.Name]
				if savedState == "true" then
					if descendant.TextColor3 == Color3.fromRGB(255, 255, 255) then
						pcall(function()
							firesignal(descendant.MouseButton1Click)
						end)
						task.wait(0.1)
					end
				end
			end
		end

		writeFile("")
		pcall(function()
			delfile(TIMESTAMP_FILE)
		end)
	end

	-- ============================================================
	-- AUTO-EXECUTE SETUP
	-- ============================================================
	local function setupAutoExecute()
		local queueFn = queue_on_teleport
			or (syn and syn.queue_on_teleport)
			or (fluxus and fluxus.queue_on_teleport)

		if queueFn then
			queueFn([[
				loadstring(game:HttpGet("https://raw.githubusercontent.com/agarv69/UNIVERSAL-SCRIPT-BY-AGARV/refs/heads/main/MonkeyGang"))()
			]])
		end
	end

	-- ============================================================
	-- HIELO DETECTION AND AUTO RESET/REJOIN
	-- ============================================================
	local function checkHielo()
		while task.wait(0.05) do
			if isOn and not isResetting then
				local char = workspace:FindFirstChild(LocalPlayer.Name)
				if char and char:FindFirstChild("Hielo") then
					isResetting = true

					-- Send reset event
					if shared.ResetCharacter then
						shared.ResetCharacter()
					else
						if LocalPlayer.Character then
							LocalPlayer.Character:BreakJoints()
						end
					end

					-- Wait up to 5 seconds for character to respawn and Hielo to be gone
					local success = false
					local startTime = tick()
					while tick() - startTime < 5 do
						LocalPlayer.CharacterAdded:Wait()
						task.wait(0.5)
						local newChar = workspace:FindFirstChild(LocalPlayer.Name)
						if newChar and not newChar:FindFirstChild("Hielo") then
							success = true
							break
						end
					end

					if not success then
						-- Still frozen or Hielo still there after 5 seconds, rejoin
						saveButtonStates()
						setupAutoExecute()
						TeleportService:TeleportToPlaceInstance(PLACE_ID, game.JobId, LocalPlayer)
						return
					end

					isResetting = false
				end
			end
		end
	end

	-- ============================================================
	-- HOVER EFFECTS
	-- ============================================================
	if MonkeyTitle then
		AntiFreeze.MouseEnter:Connect(function()
			MonkeyTitle.Text = "AUTO RESETS ON FREEZE"
		end)

		AntiFreeze.MouseLeave:Connect(function()
			MonkeyTitle.Text = "🔥THE MONKEY GANG GUI🔥"
		end)
	end

	-- ============================================================
	-- BUTTON TOGGLE
	-- ============================================================
	AntiFreeze.MouseButton1Click:Connect(function()
		isOn = not isOn

		if isOn then
			AntiFreeze.Text = "ANTI FREEZE: ON"
			AntiFreeze.TextColor3 = Color3.fromRGB(0, 255, 0)
		else
			AntiFreeze.Text = "ANTI FREEZE: OFF"
			AntiFreeze.TextColor3 = Color3.fromRGB(255, 255, 255)
		end
	end)

	-- ============================================================
	-- START HIELO MONITORING
	-- ============================================================
	task.spawn(checkHielo)

	-- ============================================================
	-- LOAD STATES ON JOIN
	-- ============================================================
	task.spawn(loadAndApplyStates)
end;
task.spawn(C_11);
