local function C_13()
local script = G2L["13"];
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local LocalPlayer = Players.LocalPlayer

	local AntiGlow = script.Parent
	local isEnabled = false
	local antiGlowConnections = {}
	local godConnections = {}

	--------------------------------------------------
	-- FIND MONKEYTITLE
	--------------------------------------------------

	local function getScreenGui()
		local p = script.Parent
		while p do
			if p:IsA("ScreenGui") then return p end
			p = p.Parent
		end
	end

	local function findDescendant(name)
		local ScreenGui = getScreenGui()
		if not ScreenGui then return nil end
		for _, v in pairs(ScreenGui:GetDescendants()) do
			if v.Name == name then return v end
		end
	end

	local MonkeyTitle = findDescendant("MonkeyTitle")

	--------------------------------------------------
	-- ANTI GLOW
	--------------------------------------------------

	local function enableAntiGlow()
		for _, conn in pairs(antiGlowConnections) do
			if conn then conn:Disconnect() end
		end
		antiGlowConnections = {}

		table.insert(antiGlowConnections, RunService.RenderStepped:Connect(function()
			if not isEnabled then return end
			local character = LocalPlayer.Character
			if not character then return end
			for _, part in pairs(character:GetDescendants()) do
				if part:IsA("BasePart") then
					if part.Material == Enum.Material.Neon then
						part.Material = Enum.Material.Plastic
					end
					if part.Color == Color3.fromRGB(0, 0, 0) then
						part.Color = Color3.fromRGB(163, 162, 165)
					end
				end
			end
		end))
	end

	local function disableAntiGlow()
		for _, conn in pairs(antiGlowConnections) do
			if conn then conn:Disconnect() end
		end
		antiGlowConnections = {}
	end

	--------------------------------------------------
	-- GOD MODE
	--------------------------------------------------

	local function enableGodMode()
		for _, c in pairs(godConnections) do
			pcall(function() c:Disconnect() end)
		end
		godConnections = {}

		table.insert(godConnections, RunService.Heartbeat:Connect(function()
			if not isEnabled then return end
			local char = LocalPlayer.Character
			if not char then return end
			local hum = char:FindFirstChildOfClass("Humanoid")
			if hum and hum.Parent then
				hum.MaxHealth = math.huge
				hum.Health = math.huge
			end
		end))
	end

	local function disableGodMode()
		for _, c in pairs(godConnections) do
			pcall(function() c:Disconnect() end)
		end
		godConnections = {}

		local char = LocalPlayer.Character
		if char then
			local hum = char:FindFirstChildOfClass("Humanoid")
			if hum then
				hum.MaxHealth = 100
				hum.Health = 100
			end
		end
	end

	--------------------------------------------------
	-- CHARACTER ADDED
	--------------------------------------------------

	LocalPlayer.CharacterAdded:Connect(function(character)
		if isEnabled then
			character:WaitForChild("Humanoid")
			task.wait(0.1)
			enableAntiGlow()
			enableGodMode()
		end
	end)

	--------------------------------------------------
	-- TOGGLE
	--------------------------------------------------

	AntiGlow.MouseButton1Click:Connect(function()
		isEnabled = not isEnabled

		if isEnabled then
			AntiGlow.Text = "ANTI GLOW, TOXIFY: ON"
			AntiGlow.TextColor3 = Color3.fromRGB(0, 255, 0)
			enableAntiGlow()
			enableGodMode()
		else
			AntiGlow.Text = "ANTI GLOW, TOXIFY: OFF"
			AntiGlow.TextColor3 = Color3.fromRGB(255, 255, 255)
			disableAntiGlow()
			disableGodMode()
		end
	end)

	--------------------------------------------------
	-- HOVER TOOLTIP
	--------------------------------------------------

	if MonkeyTitle then
		AntiGlow.MouseEnter:Connect(function()
			MonkeyTitle.Text = "PREVENTS YOU FROM DYING FROM GLOW OR TOXIFY"
		end)
		AntiGlow.MouseLeave:Connect(function()
			MonkeyTitle.Text = "🔥THE MONKEY GANG GUI🔥"
		end)
	end
end;
