	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")
	local LocalPlayer = Players.LocalPlayer

	local AntiInvis = script.Parent
	local isOn = false

	-- ============================================================
	-- FIND MONKEYTITLE
	-- ============================================================
	local function getScreenGui()
		local p = script.Parent
		while p do
			if p:IsA("ScreenGui") then
				return p
			end
			p = p.Parent
		end
	end

	local function findDescendant(name)
		local ScreenGui = getScreenGui()
		if not ScreenGui then return nil end
		for _, v in pairs(ScreenGui:GetDescendants()) do
			if v.Name == name then
				return v
			end
		end
	end

	local MonkeyTitle = findDescendant("MonkeyTitle")

	-- ============================================================
	-- TRANSPARENCY DETECTION AND AUTO RESET
	-- ============================================================
	local function checkTransparency()
		while task.wait(0.1) do
			if not isOn then continue end

			local char = workspace:FindFirstChild(LocalPlayer.Name)
			if not char then continue end

			local upperTorso = char:FindFirstChild("UpperTorso")
			if upperTorso and upperTorso.Transparency == 1 then
				-- Reset character
				if shared.ResetCharacter then
					shared.ResetCharacter()
				else
					if LocalPlayer.Character then
						LocalPlayer.Character:BreakJoints()
					end
				end

				-- Wait for respawn before checking again
				LocalPlayer.CharacterAdded:Wait()
				task.wait(1)
			end
		end
	end

	-- ============================================================
	-- HOVER EFFECTS
	-- ============================================================
	if MonkeyTitle then
		AntiInvis.MouseEnter:Connect(function()
			MonkeyTitle.Text = "AUTO RESETS WHEN INVISIBLE"
		end)

		AntiInvis.MouseLeave:Connect(function()
			MonkeyTitle.Text = "🔥THE MONKEY GANG GUI🔥"
		end)
	end

	-- ============================================================
	-- BUTTON TOGGLE
	-- ============================================================
	AntiInvis.MouseButton1Click:Connect(function()
		isOn = not isOn

		if isOn then
			AntiInvis.Text = "ANTI INVISIBLE: ON"
			AntiInvis.TextColor3 = Color3.fromRGB(0, 255, 0)
		else
			AntiInvis.Text = "ANTI INVISIBLE: OFF"
			AntiInvis.TextColor3 = Color3.fromRGB(255, 255, 255)
		end
	end)

	-- ============================================================
	-- START TRANSPARENCY MONITORING
	-- ============================================================
	task.spawn(checkTransparency)
end;
task.spawn(C_25);
-- StarterGui.MonkeyGui.MainFrame.ScrollingFrame.Right.AntiNan.AntiNanScript
local function C_27()
local script = G2L["27"];
	local Players = game:GetService("Players")
	local LocalPlayer = Players.LocalPlayer

	local AntiNan = script.Parent
	local isEnabled = false
	local connection = nil

	-- ============================================================
	-- FIND MONKEYTITLE
	-- ============================================================
	local function getScreenGui()
		local p = script.Parent
		while p do
			if p:IsA("ScreenGui") then
				return p
			end
			p = p.Parent
		end
	end

	local function findDescendant(name)
		local ScreenGui = getScreenGui()
		if not ScreenGui then return nil end
		for _, v in pairs(ScreenGui:GetDescendants()) do
			if v.Name == name then
				return v
			end
		end
	end

	local MonkeyTitle = findDescendant("MonkeyTitle")

	-- ============================================================
	-- ANTI-NAN FUNCTIONS
	-- ============================================================
	local function isNaN(n)
		return n ~= n
	end

	local function isSafe(cf)
		local p = cf.Position
		return not (isNaN(p.X) or isNaN(p.Y) or isNaN(p.Z) or
			math.abs(p.X) == math.huge or
			math.abs(p.Y) == math.huge or
			math.abs(p.Z) == math.huge)
	end

	local function onCharacterAdded(character)
		if not isEnabled then return end

		local hrp = character:WaitForChild("HumanoidRootPart")
		hrp.Anchored = true
		task.wait(0.1)

		if not isSafe(hrp.CFrame) then
			hrp.CFrame = CFrame.new(0, 50, 0)
		end

		for _, plr in pairs(Players:GetPlayers()) do
			if plr ~= LocalPlayer and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
				local otherHRP = plr.Character.HumanoidRootPart
				if isSafe(otherHRP.CFrame) then
					hrp.CFrame = otherHRP.CFrame + Vector3.new(0, 5, 0)
					break
				end
			end
		end

		hrp.Anchored = false
	end

	local function enable()
		isEnabled = true
		connection = LocalPlayer.CharacterAdded:Connect(onCharacterAdded)
		if LocalPlayer.Character then
			onCharacterAdded(LocalPlayer.Character)
		end
	end

	local function disable()
		isEnabled = false
		if connection then
			connection:Disconnect()
			connection = nil
		end
	end

	-- ============================================================
	-- BUTTON TOGGLE
	-- ============================================================
	AntiNan.MouseButton1Click:Connect(function()
		isEnabled = not isEnabled

		if isEnabled then
			AntiNan.Text = "ANTI MAPTIDE NAN: ON"
			AntiNan.TextColor3 = Color3.fromRGB(0, 255, 0)
			enable()
		else
			AntiNan.Text = "ANTI MAPTIDE NAN: OFF"
			AntiNan.TextColor3 = Color3.fromRGB(255, 255, 255)
			disable()
		end
	end)

	-- ============================================================
	-- HOVER TOOLTIP
	-- ============================================================
	if MonkeyTitle then
		AntiNan.MouseEnter:Connect(function()
			MonkeyTitle.Text = "PREVENTS YOU FROM GETTING STUCK IN THE VOID"
		end)

		AntiNan.MouseLeave:Connect(function()
			MonkeyTitle.Text = "🔥THE MONKEY GANG GUI🔥"
		end)
	end

	-- ============================================================
	-- CLEANUP
	-- ============================================================
	script.AncestryChanged:Connect(function()
		if not script:IsDescendantOf(game) then
			disable()
		end
	end)
end;
task.spawn(C_27);
