-- StarterGui.MonkeyGui.MainFrame.ScrollingFrame.Right.CloseGui.CloseGuiScript
local function C_2b()
local script = G2L["2b"];
	local CloseGui = script.Parent

	-- Find the ScreenGui (MonkeyGui)
	local function getScreenGui()
		local p = script.Parent
		while p do
			if p:IsA("ScreenGui") then
				return p
			end
			p = p.Parent
		end
	end

	-- Close button click
	CloseGui.MouseButton1Click:Connect(function()
		local MonkeyGui = getScreenGui()
		if not MonkeyGui then return end

		-- Find all toggle buttons that are ON and turn them OFF
		for _, descendant in pairs(MonkeyGui:GetDescendants()) do
			if descendant:IsA("TextButton") then
				local text = descendant.Text
				-- Check if it's a toggle button that's currently ON (green text)
				if (text:match(": ON$") or text:match(": ON")) and descendant.TextColor3 == Color3.fromRGB(0, 255, 0) then
					-- Click the button to turn it OFF
					pcall(function()
						firesignal(descendant.MouseButton1Click)
					end)
					task.wait(0.1) -- Wait between each toggle
				end
			end
		end

		-- Wait a bit for all scripts to disable
		task.wait(0.5)

		-- Now destroy the GUI
		MonkeyGui:Destroy()
	end)
end;
task.spawn(C_2b);
-- StarterGui.MonkeyGui.MainFrame.ScrollingFrame.Right.Rejoin.RejoinScript
local function C_2d()
local script = G2L["2d"];
	local Players = game:GetService("Players")
	local TeleportService = game:GetService("TeleportService")
	local LocalPlayer = Players.LocalPlayer
	local PLACE_ID = game.PlaceId
	local Rejoin = script.Parent
	local FILE_NAME = "monkeygang_rejoin_state.txt"
	local TIMESTAMP_FILE = "monkeygang_rejoin_timestamp.txt"
	-- ============================================================
	-- FIND MONKEYTITLE AND SCREENGUI
	-- ============================================================
	local function getScreenGui()
		local p = script.Parent
		while p do
			if p:IsA("ScreenGui") then
				return p
			end
			p = p.Parent
		end
	end
	local function findDescendant(name)
		local ScreenGui = getScreenGui()
		if not ScreenGui then return nil end
		for _, v in pairs(ScreenGui:GetDescendants()) do
			if v.Name == name then
				return v
			end
		end
	end
	local MonkeyTitle = findDescendant("MonkeyTitle")
	local ScreenGui = getScreenGui()
	-- ============================================================
	-- FILE SAVE/LOAD FUNCTIONS
	-- ============================================================
	local function writeFile(content)
		pcall(function()
			writefile(FILE_NAME, content)
		end)
	end
	local function saveButtonStates()
		if not ScreenGui then return end
		local lines = {}
		table.insert(lines, "autoRejoin=true")
		-- Save GUI position
		local MainFrame = ScreenGui:FindFirstChild("MainFrame")
		if MainFrame then
			local pos = MainFrame.Position
			table.insert(lines, "posXScale=" .. pos.X.Scale)
			table.insert(lines, "posXOffset=" .. pos.X.Offset)
			table.insert(lines, "posYScale=" .. pos.Y.Scale)
			table.insert(lines, "posYOffset=" .. pos.Y.Offset)
		end
		-- Find all TextButtons that are toggle buttons (have ON/OFF in text)
		for _, descendant in pairs(ScreenGui:GetDescendants()) do
			if descendant:IsA("TextButton") then
				local text = descendant.Text
				if text:match(": ON$") or text:match(": OFF$") then
					local isEnabled = descendant.TextColor3 == Color3.fromRGB(0, 255, 0)
					table.insert(lines, descendant.Name .. "=" .. tostring(isEnabled))
				end
			elseif descendant:IsA("TextBox") then
				-- Save TextBox values
				if descendant.Text ~= "" and descendant.Text ~= descendant.PlaceholderText then
					table.insert(lines, descendant.Name .. "_text=" .. descendant.Text)
				end
			end
		end
		writeFile(table.concat(lines, "\n"))
		pcall(function()
			writefile(TIMESTAMP_FILE, tostring(tick()))
		end)
	end
	-- ============================================================
	-- AUTO-EXECUTE SETUP
	-- ============================================================
	local function setupAutoExecute()
		local queueFn = queue_on_teleport
			or (syn and syn.queue_on_teleport)
			or (fluxus and fluxus.queue_on_teleport)
		if queueFn then
			queueFn([[
				loadstring(game:HttpGet("https://raw.githubusercontent.com/agarv69/UNIVERSAL-SCRIPT-BY-AGARV/refs/heads/main/MonkeyGang"))()
			]])
		end
	end
	-- ============================================================
	-- HOVER EFFECTS
	-- ============================================================
	if MonkeyTitle then
		Rejoin.MouseEnter:Connect(function()
			MonkeyTitle.Text = "MANUALLY REJOIN AND RESTORE ALL SETTINGS"
		end)
		Rejoin.MouseLeave:Connect(function()
			MonkeyTitle.Text = "🔥THE MONKEY GANG GUI🔥"
		end)
	end
	-- ============================================================
	-- BUTTON CLICK
	-- ============================================================
	Rejoin.MouseButton1Click:Connect(function()
		-- Save button states
		saveButtonStates()
		-- Setup auto-execute
		setupAutoExecute()
		-- Rejoin
		TeleportService:TeleportToPlaceInstance(PLACE_ID, game.JobId, LocalPlayer)
	end)
end;
task.spawn(C_2d);
